package coinchange;

public final class DynamicProgrammingCoinChangeSolver implements CoinChangeSolver {

    @Override
    public int countWays(CoinChangeRequest request) {
        int targetSum = request.targetSum();
        int[] waysBySum = new int[targetSum + 1];
        waysBySum[0] = 1;

        for (int coin : request.denominations().values()) {
            for (int currentSum = coin; currentSum <= targetSum; currentSum++) {
                waysBySum[currentSum] += waysBySum[currentSum - coin];
            }
        }

        return waysBySum[targetSum];
    }
}

package coinchange;

public interface CoinChangeSolver {

    int countWays(CoinChangeRequest request);

    default int countWays(int[] coins, int targetSum) {
        return countWays(new CoinChangeRequest(coins, targetSum));
    }

    default int countWays(CoinDenominations denominations, int targetSum) {
        return countWays(new CoinChangeRequest(denominations, targetSum));
    }
}

package coinchange;

public record CoinChangeRequest(CoinDenominations denominations, int targetSum) {

    public CoinChangeRequest(int[] coins, int targetSum) {
        this(new CoinDenominations(coins), targetSum);
    }

    public CoinChangeRequest {
        if (denominations == null) {
            throw new IllegalArgumentException("denominations must not be null");
        }
        validateTargetSum(targetSum);
    }

    private static void validateTargetSum(int targetSum) {
        if (targetSum < 0) {
            throw new IllegalArgumentException("targetSum must not be negative");
        }
    }
}

package coinchange;

import java.util.Arrays;
import java.util.List;

public record CoinDenominations(List<Integer> values) {

    public CoinDenominations(int[] values) {
        this(toValueList(values));
    }

    public CoinDenominations {
        validate(values);
        values = values.stream()
            .sorted()
            .distinct()
            .toList();
    }

    private static List<Integer> toValueList(int[] values) {
        if (values == null) {
            throw new IllegalArgumentException("coins must not be null");
        }

        return Arrays.stream(values)
            .boxed()
            .toList();
    }

    private static void validate(List<Integer> values) {
        if (values == null) {
            throw new IllegalArgumentException("coins must not be null");
        }

        for (Integer value : values) {
            if (value == null) {
                throw new IllegalArgumentException("coin values must not be null");
            }
            if (value <= 0) {
                throw new IllegalArgumentException("coin values must be positive");
            }
        }
    }
}

package coinchange;

import java.util.Objects;

public final class CoinChange {
    private static final CoinChange DEFAULT_INSTANCE = new CoinChange(new DynamicProgrammingCoinChangeSolver());
    private final CoinChangeSolver solver;

    public CoinChange(CoinChangeSolver solver) {
        this.solver = Objects.requireNonNull(solver, "solver must not be null");
    }

    public static int count(int[] coins, int targetSum) {
        return standard().countWays(coins, targetSum);
    }

    public static int count(CoinDenominations denominations, int targetSum) {
        return standard().countWays(denominations, targetSum);
    }

    public static int count(CoinChangeRequest request) {
        return standard().countWays(request);
    }

    public static CoinChange standard() {
        return DEFAULT_INSTANCE;
    }

    public int countWays(int[] coins, int targetSum) {
        return countWays(new CoinChangeRequest(coins, targetSum));
    }

    public int countWays(CoinDenominations denominations, int targetSum) {
        return countWays(new CoinChangeRequest(denominations, targetSum));
    }

    public int countWays(CoinChangeRequest request) {
        return solver.countWays(request);
    }

    public CoinChangeSolver solver() {
        return solver;
    }
}

package coinchange;

import java.util.Arrays;
import java.util.List;

public final class CoinChangeSelfTest {
    private static final CoinChangeSolver SOLVER = new DynamicProgrammingCoinChangeSolver();
    private static final CoinChange SERVICE = new CoinChange(SOLVER);

    private CoinChangeSelfTest() {
    }

    public static void main(String[] args) {
        assertCount(new CountCase(new int[] {1, 2, 3}, 5, 5));
        assertCount(new CountCase(new int[] {2, 5, 3, 6}, 10, 5));
        assertCount(new CountCase(new int[] {3, 1, 2, 2}, 5, 5));
        assertCount(new CountCase(new int[] {4}, 3, 0));
        assertCount(new CountCase(new int[] {}, 0, 1));
        assertCount(new CountCase(new int[] {}, 4, 0));
        assertCount(new CoinDenominations(new int[] {1, 2, 3}), 5, 5);
        assertStandardUsesDynamicProgrammingSolver();
        assertDenominationsAreNormalized();
        assertDenominationsUseValueEquality();
        assertRejects(new int[] {1, 0, 3}, 4);
        assertRejects(new int[] {1, 2, 3}, -1);
        assertRejects((int[]) null, 4);
        assertRejects((CoinDenominations) null, 4);
        assertRejects(Arrays.asList(1, null, 3));
    }

    private static void assertCount(CountCase countCase) {
        int actualWays = CoinChange.count(countCase.coins(), countCase.targetSum());
        if (actualWays != countCase.expectedWays()) {
            throw new AssertionError(
                "Expected " + countCase.expectedWays()
                    + " ways for target " + countCase.targetSum()
                    + " but got " + actualWays
            );
        }

        int serviceWays = SERVICE.countWays(countCase.coins(), countCase.targetSum());
        if (serviceWays != countCase.expectedWays()) {
            throw new AssertionError(
                "Expected service to return " + countCase.expectedWays()
                    + " ways for target " + countCase.targetSum()
                    + " but got " + serviceWays
            );
        }
    }

    private static void assertCount(CoinDenominations denominations, int targetSum, int expectedWays) {
        int actualWays = CoinChange.count(denominations, targetSum);
        if (actualWays != expectedWays) {
            throw new AssertionError(
                "Expected " + expectedWays + " ways for target " + targetSum + " but got " + actualWays
            );
        }
    }

    private static void assertRejects(int[] coins, int targetSum) {
        try {
            CoinChange.count(coins, targetSum);
            throw new AssertionError("Expected invalid input to be rejected");
        } catch (IllegalArgumentException expected) {
            // Expected path.
        }
    }

    private static void assertRejects(CoinDenominations denominations, int targetSum) {
        try {
            CoinChange.count(denominations, targetSum);
            throw new AssertionError("Expected invalid input to be rejected");
        } catch (IllegalArgumentException expected) {
            // Expected path.
        }
    }

    private static void assertDenominationsAreNormalized() {
        CoinDenominations denominations = new CoinDenominations(new int[] {3, 1, 2, 2});
        if (!denominations.values().equals(List.of(1, 2, 3))) {
            throw new AssertionError("Expected denominations to be sorted and de-duplicated");
        }
    }

    private static void assertDenominationsUseValueEquality() {
        CoinDenominations left = new CoinDenominations(new int[] {1, 2, 3});
        CoinDenominations right = new CoinDenominations(List.of(1, 2, 3));
        if (!left.equals(right)) {
            throw new AssertionError("Expected denominations with same values to be equal");
        }
    }

    private static void assertStandardUsesDynamicProgrammingSolver() {
        if (!(CoinChange.standard().solver() instanceof DynamicProgrammingCoinChangeSolver)) {
            throw new AssertionError("Expected standard CoinChange service to use the DP solver");
        }
    }

    private static void assertRejects(List<Integer> values) {
        try {
            new CoinDenominations(values);
            throw new AssertionError("Expected invalid denominations to be rejected");
        } catch (IllegalArgumentException expected) {
            // Expected path.
        }
    }

    private record CountCase(int[] coins, int targetSum, int expectedWays) {
    }
}

